function usePerm(moduleKey, action = "view") {
  const user = useContext(AuthContext);
  return hasPermission(user, moduleKey, action);
}

function useGoogleFonts() {
  useEffect(() => {
    const id = "livestock-erp-fonts";
    if (document.getElementById(id)) return;
    const link = document.createElement("link");
    link.id = id;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Zilla+Slab:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap";
    document.head.appendChild(link);
  }, []);

  // Brauzerning standart body/html margin'i (odatda 8px) `position: fixed`
  // sidebar bilan oddiy oqimdagi (normal flow) asosiy kontent orasida
  // ko'rinmas bo'shliq hosil qilardi — chunki fixed elementlar viewport
  // chetiga (0,0) yopishadi, lekin oddiy elementlar body margin'i tufayli
  // biroz ichkariga suriladi. Shu reset shu bo'shliqni butunlay yo'q qiladi.
  useEffect(() => {
    const id = "livestock-erp-reset";
    if (document.getElementById(id)) return;
    const style = document.createElement("style");
    style.id = id;
    style.textContent = `
      html, body, #root { margin: 0; padding: 0; }
      *, *::before, *::after { box-sizing: border-box; }
      body { overflow-x: hidden; }
    `;
    document.head.appendChild(style);
  }, []);
}

// ---------- Helpers ----------
const uid = () => Math.random().toString(36).slice(2, 10);

const fmtSom = (n) => {
  if (n === null || n === undefined || isNaN(n)) return "0 so'm";
  return Math.round(n).toLocaleString("fr-FR").replace(/,/g, " ") + " so'm";
};

const fmtShort = (n) => {
  if (!n) return "0";
  if (Math.abs(n) >= 1_000_000_000) return (n / 1_000_000_000).toFixed(1) + " mlrd";
  if (Math.abs(n) >= 1_000_000) return (n / 1_000_000).toFixed(1) + " mln";
  if (Math.abs(n) >= 1_000) return (n / 1_000).toFixed(0) + " ming";
  return String(n);
};

function ageFromBirth(birthDateStr) {
  if (!birthDateStr) return "—";
  const b = new Date(birthDateStr);
  if (isNaN(b.getTime())) return "—";
  const now = new Date();
  let months = (now.getFullYear() - b.getFullYear()) * 12 + (now.getMonth() - b.getMonth());
  if (now.getDate() < b.getDate()) months -= 1;
  if (months < 0) months = 0;
  const years = Math.floor(months / 12);
  const rem = months % 12;
  if (years === 0) return `${rem} oy`;
  if (rem === 0) return `${years} yosh`;
  return `${years} y ${rem} oy`;
}

