    "Homilador emas": { bg: C.rustSoft, fg: C.rustDeep, dot: "🔴" },
    "Qayta urug'lantirish": { bg: C.mode === "dark" ? "#1C2A38" : "#DDE7F0", fg: C.mode === "dark" ? "#8FB4D8" : "#3C6083", dot: "🔵" },
