// Mahsulotning joriy zaxirasi = boshlang'ich zaxira + barcha kirimlar - barcha chiqimlar
function computeFeedStock(item, transactions) {
  let kirim = 0;
  let chiqim = 0;
  transactions.forEach((t) => {
    if (t.itemId !== item.id) return;
    const q = Number(t.quantity) || 0;
    if (t.type === "Chiqim") chiqim += q;
    else kirim += q;
  });
  return (Number(item.openingStock) || 0) + kirim - chiqim;
}

