// Qoldiqni hisoblash: Umumiy summa - To'langan summa (hech qachon qo'lda o'zgartirilmaydi)
const remainingOf = (x) => Math.max(0, (Number(x.amount) || 0) - (Number(x.paidAmount) || 0));
const statusOf = (x) => {
  const rem = remainingOf(x);
  const paid = Number(x.paidAmount) || 0;
  if (rem <= 0.01 && (Number(x.amount) || 0) > 0) return "paid";
  if (paid > 0.009) return "partial";
  return "open";
};
const debtStatusLabel = (s) => (s === "paid" ? "🟢 To'langan" : s === "partial" ? "🟡 Qisman to'langan" : "🔴 To'lanmagan");
const debtStatusColor = (s) => (s === "paid" ? "#3E6B44" : s === "partial" ? "#B9812E" : "#9C3F28");

const AGING_BUCKETS = [
  { key: "0-7", label: "0–7 kun", min: 0, max: 7 },
  { key: "8-30", label: "8–30 kun", min: 8, max: 30 },
  { key: "31-60", label: "31–60 kun", min: 31, max: 60 },
  { key: "61-90", label: "61–90 kun", min: 61, max: 90 },
  { key: "90+", label: "90+ kun", min: 91, max: Infinity },
];
const overdueDays = (x, asOf) => {
  const due = x.dueDate || x.date;
  if (!due) return 0;
  const d1 = new Date(due);
  const d2 = new Date(asOf || todayStr());
  const diff = Math.floor((d2 - d1) / (1000 * 60 * 60 * 24));
  return diff;
};
const agingBucketOf = (days) => {
  if (days < 0) return null; // hali muddati kelmagan
  return AGING_BUCKETS.find((b) => days >= b.min && days <= b.max) || AGING_BUCKETS[AGING_BUCKETS.length - 1];
};

