// ---------- Oddiy CSV eksport (Excel'da ochiladi) va chop etish ----------
function exportRowsToCSV(filename, headers, rows) {
  const escape = (v) => {
    const s = v === null || v === undefined ? "" : String(v);
    if (/[",\n;]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
    return s;
  };
  const lines = [headers.map(escape).join(";"), ...rows.map((r) => r.map(escape).join(";"))];
  const csv = "\uFEFF" + lines.join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

// Chiziqli amortizatsiya: (boshlang'ich qiymat - likvidatsiya qiymati) / foydali muddat (oy)
function computeDepreciation(asset, asOfDate) {
  const initial = Number(asset.initialValue) || 0;
  const salvage = Number(asset.salvageValue) || 0;
  const lifeMonths = Math.max(1, Number(asset.usefulLifeMonths) || 1);
  const depreciable = Math.max(0, initial - salvage);
  const monthly = depreciable / lifeMonths;
  const start = asset.purchaseDate ? new Date(asset.purchaseDate) : null;
  const ref = asOfDate ? new Date(asOfDate) : new Date();
  let monthsElapsed = 0;
  if (start && !isNaN(start.getTime())) {
    monthsElapsed = (ref.getFullYear() - start.getFullYear()) * 12 + (ref.getMonth() - start.getMonth());
    if (ref.getDate() < start.getDate()) monthsElapsed -= 1;
    monthsElapsed = Math.max(0, Math.min(monthsElapsed, lifeMonths));
  }
  const accumulated = Math.min(depreciable, monthly * monthsElapsed);
  const bookValue = Math.max(salvage, initial - accumulated);
  return { monthly, accumulated, bookValue, monthsElapsed, lifeMonths };
}

// Chorvani balans hisobotidagi biologik aktiv kategoriyalariga taqsimlash
// (mavjud sex/status maydonlari asosida eng yaqin mos kategoriya tanlanadi)
function biologicalCategoryOf(a) {
  if (a.sex === "Buqa") return "Buqalar";
  if (a.sex === "Urg'ochi buzoq" || a.sex === "Erkak buzoq") return "Buzoqlar";
  if (a.status === "Bo'g'oz") return "Bo'g'oz sigirlar";
  if (a.sex === "Sigir" && a.status === "Emizayotgan") return "Sog'in sigirlar";
  if (a.sex === "Sigir") return "G'unajinlar / boshqa sigirlar";
  return "Boshqa chorva";
}

const BIOLOGICAL_CATEGORIES = ["Sog'in sigirlar", "Bo'g'oz sigirlar", "G'unajinlar / boshqa sigirlar", "Buqalar", "Buzoqlar", "Boshqa chorva"];

const UZ_MONTHS_SHORT = ["Yan", "Fev", "Mar", "Apr", "May", "Iyun", "Iyul", "Avg", "Sen", "Okt", "Noy", "Dek"];

// Oxirgi N oy bo'yicha daromad/xarajat dinamikasi (haqiqiy xarajat yozuvlari
// va shu oyda sotib olingan mollarning qiymat o'sishi asosida hisoblanadi).
function getMonthlyTrend(animals, expenses, months = 6) {
  const now = new Date();
  const buckets = [];
  for (let i = months - 1; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    buckets.push({ year: d.getFullYear(), month: d.getMonth(), label: UZ_MONTHS_SHORT[d.getMonth()] });
  }
  return buckets.map(({ year, month, label }) => {
    const xarajat = expenses.reduce((s, x) => {
      const d = new Date(x.date);
      if (d.getFullYear() === year && d.getMonth() === month) return s + (Number(x.amount) || 0);
      return s;
    }, 0);
    const daromad = animals.reduce((s, a) => {
      const d = new Date(a.purchaseDate);
      if (d.getFullYear() === year && d.getMonth() === month) {
        const farq = (Number(a.currentValue) || 0) - (Number(a.purchasePrice) || 0);
        return s + (farq > 0 ? farq : 0);
      }
      return s;
    }, 0);
    return { label, daromad, xarajat };
  });
}

function isSameMonth(dateStr, ref) {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  return d.getFullYear() === ref.getFullYear() && d.getMonth() === ref.getMonth();
}

// ---------- Period range (Davr tanlash) ----------
function startOfDay(d) { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; }
function endOfDay(d) { const x = new Date(d); x.setHours(23, 59, 59, 999); return x; }

function getPeriodRange(customFrom, customTo) {
  if (!customFrom || !customTo) return { start: null, end: null };
  return { start: startOfDay(new Date(customFrom)), end: endOfDay(new Date(customTo)) };
}

function inRange(dateStr, start, end) {
  if (!dateStr) return false;
  if (!start || !end) return true;
  const d = new Date(dateStr);
  return d >= start && d <= end;
}

function fmtDateUz(d) {
  if (!d) return "";
  const dt = d instanceof Date ? d : new Date(d);
  if (isNaN(dt.getTime())) return "";
  const dd = String(dt.getDate()).padStart(2, "0");
  const mm = String(dt.getMonth() + 1).padStart(2, "0");
  const yyyy = dt.getFullYear();
  return `${dd}.${mm}.${yyyy}`;
}

const UZ_MONTHS_LOWER = [
  "yanvar", "fevral", "mart", "aprel", "may", "iyun",
  "iyul", "avgust", "sentyabr", "oktyabr", "noyabr", "dekabr",
];

function fmtDateUzLong(d) {
  if (!d) return "";
  const dt = d instanceof Date ? d : new Date(d);
  if (isNaN(dt.getTime())) return "";
  return `${dt.getDate()}-${UZ_MONTHS_LOWER[dt.getMonth()]}, ${dt.getFullYear()}`;
}

