// ---------- Feed kirim/chiqim (harakat) form modal ----------
function FeedTxModal({ initial, feedItems, onClose, onSave }) {
  const C = useContext(ThemeContext);
  const [form, setForm] = useState(initial);
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const updateItemOrQty = (patch) => {
    setForm((f) => {
      const next = { ...f, ...patch };
      const item = feedItems.find((i) => i.id === next.itemId);
      const qty = Number(next.quantity) || 0;
      const price = Number(item?.pricePerUnit) || 0;
      if (next.type === "Kirim" && qty > 0 && price > 0) next.amount = String(qty * price);
      return next;
    });
  };

  const inputCls = "w-full rounded-lg border px-3 py-2 text-sm focus:outline-none focus:ring-2";
  const inputStyle = { borderColor: C.line, background: C.surfaceSoft, color: C.ink, colorScheme: "light" };
  const selectedItem = feedItems.find((i) => i.id === form.itemId);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ background: "rgba(14,23,18,0.55)", backdropFilter: "blur(2px)" }}>
      <div className="w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden" style={{ background: C.base, fontFamily: "'IBM Plex Sans', sans-serif" }}>
        <div className="flex items-center justify-between px-6 py-4" style={{ background: GRAD.sidebar }}>
          <h2 style={{ fontFamily: "'Zilla Slab', serif", color: "#fff" }} className="text-lg font-semibold">
            Ombor harakati (Kirim / Chiqim)
          </h2>
          <button onClick={onClose} className="text-white/80 hover:text-white">
            <X size={20} />
          </button>
        </div>
        <div className="p-6 grid grid-cols-2 gap-4">
          <div className="col-span-2">
            <label className="text-xs" style={{ color: C.inkSoft }}>Mahsulot *</label>
            <select className={inputCls} style={inputStyle} value={form.itemId} onChange={(e) => updateItemOrQty({ itemId: e.target.value })}>
              <option value="">— Tanlang —</option>
              {feedItems.map((i) => (<option key={i.id} value={i.id}>{i.name} ({i.unit})</option>))}
            </select>
          </div>
          <div>
            <label className="text-xs" style={{ color: C.inkSoft }}>Turi *</label>
            <select className={inputCls} style={inputStyle} value={form.type} onChange={set("type")}>
              <option value="Kirim">Kirim (+)</option>
              <option value="Chiqim">Chiqim (-)</option>
            </select>
          </div>
          <div>
            <label className="text-xs" style={{ color: C.inkSoft }}>Sana *</label>
            <input type="date" className={inputCls} style={inputStyle} value={form.date} onChange={set("date")} />
          </div>
          <div>
            <label className="text-xs" style={{ color: C.inkSoft }}>
              Miqdor {selectedItem ? `(${selectedItem.unit})` : ""} *
            </label>
            <input type="number" className={inputCls} style={inputStyle} value={form.quantity} onChange={(e) => updateItemOrQty({ quantity: e.target.value })} placeholder="0" />
          </div>
          {form.type === "Kirim" && (
            <>
              <div>
                <label className="text-xs" style={{ color: C.inkSoft }}>Xarid summasi (so'm)</label>
                <input type="number" className={inputCls} style={inputStyle} value={form.amount || ""} onChange={set("amount")} placeholder="0" />
              </div>
              <div>
                <label className="text-xs" style={{ color: C.inkSoft }}>Kimga to'landi</label>
                <input className={inputCls} style={inputStyle} value={form.paidTo || ""} onChange={set("paidTo")} placeholder="Yetkazib beruvchi" />
              </div>
              <label className="col-span-2 flex items-center gap-2 text-xs" style={{ color: C.inkSoft }}>
                <input type="checkbox" checked={form.payFromCash !== false} onChange={(e) => setForm((f) => ({ ...f, payFromCash: e.target.checked }))} />
                Kassadan to'landi — summa Kassa / Pul oqimidan avtomatik ayriladi
              </label>
            </>
          )}
          <div className="col-span-2">
            <label className="text-xs" style={{ color: C.inkSoft }}>Izoh</label>
            <textarea className={inputCls} style={inputStyle} rows={2} value={form.note} onChange={set("note")} placeholder="Masalan: yetkazib beruvchidan, yoki qaysi molga berildi" />
          </div>
        </div>
        <div className="flex justify-end gap-2 px-6 py-4" style={{ borderTop: `1px solid ${C.line}` }}>
          <button onClick={onClose} className="px-4 py-2 rounded-lg text-sm" style={{ color: C.inkSoft, border: `1px solid ${C.line}` }}>
            Bekor qilish
          </button>
          <button
            onClick={() => {
              if (!form.itemId || !form.date || !form.quantity || Number(form.quantity) <= 0) return;
              onSave({ ...form, quantity: Number(form.quantity), amount: Number(form.amount) || 0 });
            }}
            className="px-4 py-2 rounded-lg text-sm font-medium text-white"
            style={{ background: form.type === "Chiqim" ? GRAD.rust : GRAD.moss }}
          >
            Saqlash
          </button>
        </div>
      </div>
    </div>
  );
}

