function ReproBadge({ status }) {
  const C = useContext(ThemeContext);
  const s = getReproStatusStyle(C)[status] || getReproStatusStyle(C)["Rejalashtirilgan"];
  return (
    <span
      className="px-2 py-1 rounded-full text-xs font-medium inline-flex items-center gap-1 whitespace-nowrap"
      style={{ background: s.bg, color: s.fg }}
    >
      <span>{s.dot}</span> {status}
    </span>
  );
}

function ReproKpiCards({ stats }) {
  return (
    <div className="grid grid-cols-3 lg:grid-cols-6 gap-4 mb-6">
      <KpiCard icon={Syringe} label="Bugun urug'lantirilgan" value={stats.todayCount} sub="Bugungi yozuvlar" grad={GRAD.moss} />
      <KpiCard icon={CalendarClock} label="Shu oy urug'lantirilgan" value={stats.monthCount} sub="Joriy oy" grad={GRAD.sky} />
      <KpiCard icon={Baby} label="Homilador sigirlar" value={stats.pregnantCount} sub={`Homiladorlik ${stats.pregnancyRate}%`} grad={GRAD.gold} />
      <KpiCard icon={Stethoscope} label="Homiladorligi aniqlanmagan" value={stats.pendingCheck} sub="Tekshiruv kutilmoqda" grad={GRAD.slate} />
      <KpiCard icon={RefreshCw} label="Qayta urug'lantirish kerak" value={stats.needsRebreed} sub={`Qayta urug'lantirish ${stats.repeatBreedingRate}%`} grad={GRAD.rust} />
      <KpiCard icon={ClipboardCheck} label="Yaqin tug'ruqlar" value={stats.upcomingBirths} sub="Keyingi 30 kun ichida" grad={GRAD.plum} />
    </div>
  );
}

function ReproNotifications({ notifs, animals, onOpenAnimal }) {
  const C = useContext(ThemeContext);
  const findTag = (id) => animals.find((a) => a.id === id)?.tag || "—";
  const items = [
    notifs.todayChecks.length > 0 && {
      icon: "🔔",
      text: `Bugun tekshiruvga kelishi kerak: ${notifs.todayChecks.map((i) => findTag(i.animalId)).join(", ")}`,
      tone: C.goldSoft,
      fg: C.goldDeep,
    },
    notifs.rebreedDue.length > 0 && {
      icon: "🔔",
      text: `Qayta urug'lantirish vaqti kelgan: ${notifs.rebreedDue.map((i) => findTag(i.animalId)).join(", ")}`,
      tone: C.rustSoft,
      fg: C.rustDeep,
    },
    notifs.births7.length > 0 && {
      icon: "🔔",
      text: `7 kun ichida tug'ishi kutilmoqda: ${notifs.births7.map((i) => findTag(i.animalId)).join(", ")}`,
      tone: C.mossSoft,
      fg: C.mossDeep,
    },
    notifs.overdueChecks.length > 0 && {
      icon: "🔔",
      text: `Homiladorlik tekshiruvi kechikkan: ${notifs.overdueChecks.map((i) => findTag(i.animalId)).join(", ")}`,
      tone: C.mode === "dark" ? "#1C2A38" : "#DDE7F0",
      fg: C.mode === "dark" ? "#8FB4D8" : "#3C6083",
    },
  ].filter(Boolean);

  if (items.length === 0) return null;

  return (
    <div className="flex flex-col gap-2 mb-6">
      {items.map((it, i) => (
        <div key={i} className="flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm" style={{ background: it.tone, color: it.fg }}>
          <Bell size={14} /> <span>{it.text}</span>
        </div>
      ))}
    </div>
  );
}

