function AnimalReproHistoryDrawer({ animal, records, onClose }) {
  const C = useContext(ThemeContext);
  const sorted = [...records].sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  const total = sorted.length;
  const success = sorted.filter((r) => r.checkResult === "Homilador").length;
  const births = sorted.filter((r) => r.actualBirthDate);
  const avgDays = (() => {
    const diffs = births.map((r) => daysBetween(r.date, r.actualBirthDate)).filter((d) => d !== null);
    if (!diffs.length) return null;
    return Math.round(diffs.reduce((s, d) => s + d, 0) / diffs.length);
  })();

  return (
    <div className="fixed inset-0 z-50 flex justify-end" style={{ background: "rgba(14,23,18,0.5)" }}>
      <div className="w-full max-w-md h-full overflow-y-auto shadow-2xl" style={{ background: C.base, fontFamily: "'IBM Plex Sans', sans-serif" }}>
        <div className="flex items-center justify-between px-6 py-4 sticky top-0 z-10" style={{ background: GRAD.sidebar }}>
          <h2 style={{ fontFamily: "'Zilla Slab', serif", color: "#fff" }} className="text-lg font-semibold flex items-center gap-2">
            <History size={18} /> Reproduktiv tarix — {animal?.tag}
          </h2>
          <button onClick={onClose} className="text-white/80 hover:text-white"><X size={20} /></button>
        </div>
        <div className="p-6">
          <div className="grid grid-cols-3 gap-3 mb-6">
            <div className="rounded-xl p-3 text-center" style={{ background: C.surfaceSoft, border: `1px solid ${C.line}` }}>
              <div className="text-xl font-semibold" style={{ color: C.ink, fontFamily: "'IBM Plex Mono', monospace" }}>{total}</div>
              <div className="text-[11px]" style={{ color: C.inkSoft }}>Urug'lantirishlar</div>
            </div>
            <div className="rounded-xl p-3 text-center" style={{ background: C.surfaceSoft, border: `1px solid ${C.line}` }}>
              <div className="text-xl font-semibold" style={{ color: C.mossDeep, fontFamily: "'IBM Plex Mono', monospace" }}>{success}</div>
              <div className="text-[11px]" style={{ color: C.inkSoft }}>Muvaffaqiyatli</div>
            </div>
            <div className="rounded-xl p-3 text-center" style={{ background: C.surfaceSoft, border: `1px solid ${C.line}` }}>
              <div className="text-xl font-semibold" style={{ color: C.ink, fontFamily: "'IBM Plex Mono', monospace" }}>{avgDays !== null ? `${avgDays}k` : "—"}</div>
              <div className="text-[11px]" style={{ color: C.inkSoft }}>O'rtacha urug'lantirish→tug'ruq</div>
            </div>
          </div>

          {sorted.length === 0 ? (
            <p className="text-sm text-center py-8" style={{ color: C.inkSoft }}>Bu sigir uchun reproduktiv yozuvlar yo'q.</p>
          ) : (
            <div className="flex flex-col gap-4">
              {sorted.map((r, idx) => (
                <div key={r.id} className="relative pl-6">
                  <div className="absolute left-0 top-1.5 w-2.5 h-2.5 rounded-full" style={{ background: GRAD.moss }} />
                  {idx < sorted.length - 1 && <div className="absolute left-[4px] top-4 bottom-[-16px] w-px" style={{ background: C.line }} />}
                  <div className="text-xs" style={{ color: C.inkSoft, fontFamily: "'IBM Plex Mono', monospace" }}>{r.date}</div>
                  <div className="text-sm font-medium" style={{ color: C.ink }}>{r.method} · {r.attemptNumber}</div>
                  <div className="text-xs mt-0.5"><ReproBadge status={r.status} /></div>
                  {r.checkDate && (
                    <div className="text-xs mt-1" style={{ color: C.inkSoft }}>Tekshiruv: {r.checkDate} — {r.checkResult} ({r.checkVet})</div>
                  )}
                  {r.expectedBirthDate && (
                    <div className="text-xs" style={{ color: C.inkSoft }}>Kutilayotgan tug'ruq: {r.expectedBirthDate}</div>
                  )}
                  {r.actualBirthDate && (
                    <div className="text-xs" style={{ color: C.mossDeep }}>Tug'ruq: {r.actualBirthDate}</div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function ReproReports({ inseminations, animals }) {
  const C = useContext(ThemeContext);
  const stats = computeReproStats(animals, inseminations);

  const monthly = useMemo(() => {
    const map = {};
    for (const i of inseminations) {
      const k = (i.date || "").slice(0, 7);
      if (!k) continue;
      map[k] = (map[k] || 0) + 1;
    }
    return Object.entries(map).sort(([a], [b]) => a.localeCompare(b)).slice(-12).map(([k, v]) => ({ month: k, count: v }));
  }, [inseminations]);

  const byVet = useMemo(() => {
    const map = {};
    for (const i of inseminations.filter((x) => x.checkResult)) {
      const vet = i.checkVet || "Noma'lum";
      if (!map[vet]) map[vet] = { total: 0, success: 0 };
      map[vet].total += 1;
      if (i.checkResult === "Homilador") map[vet].success += 1;
    }
    return Object.entries(map).map(([vet, v]) => ({ vet, rate: Math.round((v.success / v.total) * 100), total: v.total }));
  }, [inseminations]);

  const byBreed = useMemo(() => {
    const map = {};
    for (const i of inseminations.filter((x) => x.checkResult)) {
      const a = animals.find((x) => x.id === i.animalId);
      const breed = a?.breed || "Noma'lum";
      if (!map[breed]) map[breed] = { total: 0, success: 0 };
      map[breed].total += 1;
      if (i.checkResult === "Homilador") map[breed].success += 1;
    }
    return Object.entries(map).map(([breed, v]) => ({ breed, rate: Math.round((v.success / v.total) * 100), total: v.total }));
  }, [inseminations, animals]);

  const donutData = [
    { name: "Homilador", value: inseminations.filter((i) => i.status === "Homilador").length, color: C.moss },
    { name: "Tekshiruv kutilmoqda", value: inseminations.filter((i) => i.status === "Tekshiruv kutilmoqda").length, color: C.gold },
    { name: "Homilador emas", value: inseminations.filter((i) => i.status === "Homilador emas").length, color: C.rust },
    { name: "Qayta urug'lantirish", value: inseminations.filter((i) => i.status === "Qayta urug'lantirish").length, color: "#6E93B8" },
    { name: "Rejalashtirilgan", value: inseminations.filter((i) => i.status === "Rejalashtirilgan").length, color: C.inkSoft },
  ].filter((d) => d.value > 0);

  const statBox = (label, value) => (
    <div className="rounded-xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: C.shadow }}>
      <div className="text-xs" style={{ color: C.inkSoft }}>{label}</div>
      <div className="text-xl font-semibold mt-1" style={{ color: C.ink, fontFamily: "'IBM Plex Mono', monospace" }}>{value}</div>
    </div>
  );

  return (
    <div className="flex flex-col gap-6">
      <div className="grid grid-cols-3 lg:grid-cols-6 gap-3">
        {statBox("Jami urug'lantirishlar", inseminations.length)}
        {statBox("Muvaffaqiyatli %", `${stats.successRate}%`)}
        {statBox("Homiladorlik darajasi", `${stats.pregnancyRate}%`)}
        {statBox("Qayta urug'lantirish %", `${stats.repeatBreedingRate}%`)}
        {statBox("O'rtacha urinish/sigir", stats.avgAttempts)}
        {statBox("Faol homilador", stats.pregnantCount)}
      </div>

      <div className="grid grid-cols-2 gap-6">
        <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: C.shadow }}>
          <h3 className="text-sm font-semibold mb-3" style={{ color: C.ink }}>Oylar bo'yicha urug'lantirish</h3>
          <ResponsiveContainer width="100%" height={220}>
            <BarChart data={monthly}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.line} />
              <XAxis dataKey="month" tick={{ fontSize: 11, fill: C.inkSoft }} />
              <YAxis tick={{ fontSize: 11, fill: C.inkSoft }} allowDecimals={false} />
              <Tooltip />
              <Bar dataKey="count" fill={C.moss} radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: C.shadow }}>
          <h3 className="text-sm font-semibold mb-3" style={{ color: C.ink }}>Status taqsimoti</h3>
          <ResponsiveContainer width="100%" height={220}>
            <RePieChart>
              <Pie data={donutData} dataKey="value" nameKey="name" innerRadius={50} outerRadius={80} paddingAngle={2}>
                {donutData.map((d, i) => (<Cell key={i} fill={d.color} />))}
              </Pie>
              <Tooltip />
              <Legend wrapperStyle={{ fontSize: 11 }} />
            </RePieChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-6">
        <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: C.shadow }}>
          <h3 className="text-sm font-semibold mb-3" style={{ color: C.ink }}>Veterinarlar bo'yicha natijalar</h3>
          {byVet.length === 0 ? (
            <p className="text-xs" style={{ color: C.inkSoft }}>Hozircha ma'lumot yo'q.</p>
          ) : (
            <div className="flex flex-col gap-2">
              {byVet.map((v) => (
                <div key={v.vet} className="flex items-center justify-between text-xs">
                  <span style={{ color: C.ink }}>{v.vet} <span style={{ color: C.inkSoft }}>({v.total})</span></span>
                  <span style={{ color: C.mossDeep, fontFamily: "'IBM Plex Mono', monospace" }}>{v.rate}%</span>
                </div>
              ))}
            </div>
          )}
        </div>
        <div className="rounded-2xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: C.shadow }}>
          <h3 className="text-sm font-semibold mb-3" style={{ color: C.ink }}>Zoti bo'yicha natijalar</h3>
          {byBreed.length === 0 ? (
            <p className="text-xs" style={{ color: C.inkSoft }}>Hozircha ma'lumot yo'q.</p>
          ) : (
            <div className="flex flex-col gap-2">
              {byBreed.map((v) => (
                <div key={v.breed} className="flex items-center justify-between text-xs">
                  <span style={{ color: C.ink }}>{v.breed} <span style={{ color: C.inkSoft }}>({v.total})</span></span>
                  <span style={{ color: C.mossDeep, fontFamily: "'IBM Plex Mono', monospace" }}>{v.rate}%</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ---------- Reproduction Management — top-level module ----------
function ReproductionModule({ animals, inseminations, onSave, onDelete, role, setRole }) {
  const C = useContext(ThemeContext);
  const [tab, setTab] = useState("dashboard");
  const [modalIns, setModalIns] = useState(null);
  const [modalInsIsNew, setModalInsIsNew] = useState(true);
  const [modalCheck, setModalCheck] = useState(null);
  const [modalBirth, setModalBirth] = useState(null);
  const [confirmDel, setConfirmDel] = useState(null);
  const [historyAnimal, setHistoryAnimal] = useState(null);
  const [filters, setFilters] = useState({ q: "", from: "", to: "", breed: "", status: "", method: "", vet: "" });

  const stats = useMemo(() => computeReproStats(animals, inseminations), [animals, inseminations]);
  const notifs = useMemo(() => reproNotifications(inseminations), [inseminations]);

  const filtered = useMemo(() => {
    return inseminations
      .filter((i) => {
        const a = animals.find((x) => x.id === i.animalId);
        if (filters.q) {
          const q = filters.q.toLowerCase();
          const hay = `${a?.tag || ""} ${a?.id || ""} ${a?.name || ""}`.toLowerCase();
          if (!hay.includes(q)) return false;
        }
        if (filters.from && i.date < filters.from) return false;
        if (filters.to && i.date > filters.to) return false;
        if (filters.breed && a?.breed !== filters.breed) return false;
        if (filters.status && i.status !== filters.status) return false;
        if (filters.method && i.method !== filters.method) return false;
        if (filters.vet && !(i.operator || "").toLowerCase().includes(filters.vet.toLowerCase()) && !(i.checkVet || "").toLowerCase().includes(filters.vet.toLowerCase())) return false;
        return true;
      })
      .sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  }, [inseminations, animals, filters]);

  const tabBtnStyle = (key) => ({
    background: tab === key ? GRAD.moss : "transparent",
    color: tab === key ? "#fff" : C.inkSoft,
    border: tab === key ? "none" : `1px solid ${C.line}`,
  });

  const handleSaveCheck = (checkForm) => {
    const ins = modalCheck;
    const status = checkForm.checkResult === "Homilador" ? "Homilador" : "Qayta urug'lantirish";
    onSave({
      ...ins,
      ...checkForm,
      status,
      expectedBirthDate: checkForm.checkResult === "Homilador" ? addDays(ins.date, GESTATION_DAYS) : "",
      updatedAt: new Date().toISOString(),
    });
    setModalCheck(null);
  };

  const handleSaveBirth = (date) => {
    onSave({ ...modalBirth, actualBirthDate: date, updatedAt: new Date().toISOString() });
    setModalBirth(null);
  };

  return (
    <div className="flex flex-col">
      <div className="flex items-center justify-between mb-5 flex-wrap gap-3">
        <div className="flex gap-2">
          <button onClick={() => setTab("dashboard")} className="px-4 py-2 rounded-xl text-sm font-medium" style={tabBtnStyle("dashboard")}>Dashboard</button>
          <button onClick={() => setTab("journal")} className="px-4 py-2 rounded-xl text-sm font-medium" style={tabBtnStyle("journal")}>Urug'lantirish jurnali</button>
          <button onClick={() => setTab("reports")} className="px-4 py-2 rounded-xl text-sm font-medium" style={tabBtnStyle("reports")}>Reproduktiv hisobotlar</button>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 text-xs" style={{ color: C.inkSoft }}>
            <UserCog size={14} />
            <select
              className="rounded-lg border px-2 py-1.5 text-xs"
              style={{ borderColor: C.line, background: C.surfaceSoft, color: C.ink }}
              value={role}
              onChange={(e) => setRole(e.target.value)}
            >
              {REPRO_ROLES.map((r) => (<option key={r} value={r}>{r}</option>))}
            </select>
          </div>
          {role !== "Auditor" && (
            <button
              onClick={() => { setModalIns(emptyInsemination()); setModalInsIsNew(true); }}
              className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium text-white"
              style={{ background: GRAD.moss, boxShadow: "0 8px 18px -8px rgba(63,107,68,0.7)" }}
            >
              <Plus size={16} /> Yangi urug'lantirish
            </button>
          )}
        </div>
      </div>

      {tab === "dashboard" && (
        <>
          <ReproNotifications notifs={notifs} animals={animals} />
          <ReproKpiCards stats={stats} />
          <ReproFilterBar filters={filters} setFilters={setFilters} animals={animals} />
          <ReproJournalTable
            rows={filtered.slice(0, 8)}
            animals={animals}
            role={role}
            onCheck={(ins) => setModalCheck(ins)}
            onBirth={(ins) => setModalBirth(ins)}
            onEdit={(ins) => { setModalIns(ins); setModalInsIsNew(false); }}
            onDelete={(ins) => setConfirmDel(ins)}
            onOpenHistory={(a) => setHistoryAnimal(a)}
          />
        </>
      )}

      {tab === "journal" && (
        <>
          <ReproFilterBar filters={filters} setFilters={setFilters} animals={animals} />
          <ReproJournalTable
            rows={filtered}
            animals={animals}
            role={role}
            onCheck={(ins) => setModalCheck(ins)}
            onBirth={(ins) => setModalBirth(ins)}
            onEdit={(ins) => { setModalIns(ins); setModalInsIsNew(false); }}
            onDelete={(ins) => setConfirmDel(ins)}
            onOpenHistory={(a) => setHistoryAnimal(a)}
          />
        </>
      )}

      {tab === "reports" && <ReproReports inseminations={inseminations} animals={animals} />}

      {modalIns && (
        <InseminationModal
          initial={modalIns}
          animals={animals}
          isNew={modalInsIsNew}
          onClose={() => setModalIns(null)}
          onSave={(form) => { onSave(form); setModalIns(null); }}
        />
      )}

      {modalCheck && (
        <PregnancyCheckModal
          initial={modalCheck}
          animal={animals.find((a) => a.id === modalCheck.animalId)}
          onClose={() => setModalCheck(null)}
          onSave={handleSaveCheck}
        />
      )}

      {modalBirth && (
        <BirthRecordModal
          animal={animals.find((a) => a.id === modalBirth.animalId)}
          onClose={() => setModalBirth(null)}
          onSave={handleSaveBirth}
        />
      )}

      {historyAnimal && (
        <AnimalReproHistoryDrawer
          animal={historyAnimal}
          records={inseminations.filter((i) => i.animalId === historyAnimal.id)}
          onClose={() => setHistoryAnimal(null)}
        />
      )}

      {confirmDel && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ background: "rgba(14,23,18,0.55)" }}>
          <div className="w-full max-w-sm rounded-2xl p-6" style={{ background: C.base }}>
            <h3 className="text-base font-semibold mb-2" style={{ color: C.ink }}>Yozuvni o'chirasizmi?</h3>
            <p className="text-sm mb-5" style={{ color: C.inkSoft }}>Bu amalni bekor qilib bo'lmaydi.</p>
            <div className="flex justify-end gap-2">
              <button onClick={() => setConfirmDel(null)} className="px-4 py-2 rounded-lg text-sm" style={{ color: C.inkSoft, border: `1px solid ${C.line}` }}>Bekor qilish</button>
              <button onClick={() => { onDelete(confirmDel.id); setConfirmDel(null); }} className="px-4 py-2 rounded-lg text-sm font-medium text-white" style={{ background: GRAD.rust }}>O'chirish</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// =====================================================================================
// ============================  BUDJET MODULI (BUDGET)  ==============================
// =====================================================================================
// Budget = REJA (rejalashtirish/forecast). Xarajatlar/Kassa/P&L/Balans — haqiqiy holat.
// Budget ma'lumotlari haqiqiy accounting transaction hisoblanmaydi; faqat rejalashtirish,
// forecast, reminder, variance analysis va cash planning uchun ishlatiladi (bo'lim 2, 40).

// Budget kategoriyalari Xarajatlar bilan bir xil master ro'yxatdan foydalanadi (bo'lim 6).
const BUDGET_CATEGORIES = EXPENSE_CATEGORIES;
const BUDGET_INCOME_CATEGORIES = CASH_IN_CATEGORIES;
const BUDGET_FREQUENCIES = [
  "Bir martalik", "Har kuni", "Har hafta", "Har 2 hafta", "Har oy", "Har chorak", "Har 6 oy", "Har yil",
];
const BUDGET_PRIORITIES = ["Critical", "High", "Medium", "Low"];
const BUDGET_CONFIDENCE = ["Confirmed", "Likely", "Possible"];
const BUDGET_TAB_LIST = [
  { key: "umumiy", label: "Umumiy" },
  { key: "rejalar", label: "Rejalar" },
  { key: "tolovlar", label: "Kelgusi to'lovlar" },
  { key: "kalendar", label: "Kalendar" },
  { key: "bva", label: "Budget vs Actual" },
  { key: "forecast", label: "Forecast" },
  { key: "alerts", label: "Ogohlantirishlar" },
];

const emptyBudgetItem = () => ({
  id: uid(),
  name: "",
  category: "Ozuqa",
  type: "EXPENSE", // EXPENSE | INCOME
  amount: "",
  currency: "UZS",
  startDate: todayStr(),
  endDate: "",
  paymentDay: "",
  frequency: "Har oy",
  priority: "Medium",
  mandatory: true,
  confidence: "Confirmed", // faqat INCOME uchun mazmunli (bo'lim 10)
  status: "ACTIVE", // ACTIVE | PAUSED | ENDED | CANCELLED
  reminderDays: [7, 3, 1, 0],
  note: "",
});

function addMonthsStr(dateStr, months, dayOverride) {
  const d = new Date(dateStr);
  const day = dayOverride || d.getDate();
  const nd = new Date(d.getFullYear(), d.getMonth() + months, day);
  return nd;
}

// Berilgan budget reja uchun [rangeStart, rangeEnd] oralig'idagi barcha to'lov sanalarini hosil qiladi
// (bo'lim 5 — Recurring Expense Engine).
function generateOccurrenceDates(item, rangeStartStr, rangeEndStr) {
  if (!item.startDate) return [];
  const rs = startOfDay(new Date(rangeStartStr));
  const re = endOfDay(new Date(rangeEndStr));
  const start = startOfDay(new Date(item.startDate));
  const end = item.endDate ? endOfDay(new Date(item.endDate)) : re;
  const lo = start > rs ? start : rs;
  const hi = end < re ? end : re;
  if (lo > hi) return [];
  const freq = item.frequency || "Har oy";
  const dates = [];

  if (freq === "Bir martalik") {
    if (start >= rs && start <= re) dates.push(start.toISOString().slice(0, 10));
    return dates;
  }

  const stepDaysMap = { "Har kuni": 1, "Har hafta": 7, "Har 2 hafta": 14 };
  if (stepDaysMap[freq]) {
    const step = stepDaysMap[freq];
    let cur = new Date(start);
    let guard = 0;
    while (cur <= hi && guard < 2000) {
      if (cur >= lo) dates.push(cur.toISOString().slice(0, 10));
      cur = new Date(cur.getFullYear(), cur.getMonth(), cur.getDate() + step);
      guard++;
    }
    return dates;
  }

  const stepMonths = freq === "Har oy" ? 1 : freq === "Har chorak" ? 3 : freq === "Har 6 oy" ? 6 : freq === "Har yil" ? 12 : 1;
  const day = item.paymentDay ? Number(item.paymentDay) : start.getDate();
  let cur = new Date(start.getFullYear(), start.getMonth(), day);
  let guard = 0;
  while (cur <= hi && guard < 600) {
    if (cur >= lo && cur >= start) dates.push(cur.toISOString().slice(0, 10));
    cur = addMonthsStr(cur.toISOString().slice(0, 10), stepMonths, day);
    guard++;
  }
  return dates;
}

// Barcha faol budget rejalar bo'yicha [rangeStart, rangeEnd] oralig'idagi occurrencelarni yig'adi.
function buildBudgetOccurrences(budgetItems, rangeStartStr, rangeEndStr) {
  const list = [];
  (budgetItems || [])
    .filter((b) => b.status !== "CANCELLED" && b.status !== "ENDED" && b.status !== "PAUSED")
    .forEach((item) => {
      const dates = generateOccurrenceDates(item, rangeStartStr, rangeEndStr);
      dates.forEach((d) => {
        list.push({
          id: `${item.id}__${d}`,
          itemId: item.id,
          name: item.name,
          category: item.category,
          type: item.type || "EXPENSE",
          amount: Number(item.amount) || 0,
          date: d,
          priority: item.priority || "Medium",
          mandatory: item.mandatory !== false,
          confidence: item.confidence || "Confirmed",
        });
      });
    });
  list.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  return list;
}

function occurrenceStatus(dateStr) {
  const today = todayStr();
  if (dateStr < today) return "OVERDUE";
  if (dateStr === today) return "DUE";
  return "PLANNED";
}

function occurrenceStatusStyle(status, C) {
  const map = {
    OVERDUE: { bg: C.rustSoft, fg: C.rustDeep },
    DUE: { bg: C.goldSoft, fg: C.goldDeep },
    PLANNED: { bg: C.surfaceSoft, fg: C.inkSoft },
    PAID: { bg: C.mossSoft, fg: C.mossDeep },
  };
  return map[status] || map.PLANNED;
}

// Variance thresholdlari (bo'lim 25): 0-5% normal, 5-10% warning, 10-20% high, 20%+ critical.
function varianceStatus(budget, actual) {
  const b = Number(budget) || 0;
  const a = Number(actual) || 0;
  if (b === 0 && a > 0) return { variance: a, pct: null, status: "REJALASHTIRILMAGAN XARAJAT", level: "critical" };
  if (b === 0 && a === 0) return { variance: 0, pct: 0, status: "—", level: "none" };
  const variance = a - b;
  const pct = (variance / b) * 100;
  const abspct = Math.abs(pct);
  const level = abspct <= 5 ? "normal" : abspct <= 10 ? "warning" : abspct <= 20 ? "high" : "critical";
  const dir = variance > 0 ? "OVER BUDGET" : variance < 0 ? "UNDER BUDGET" : "ON BUDGET";
  return { variance, pct, status: abspct <= 5 ? "ON BUDGET" : dir, level };
}

function varianceLevelStyle(level, C) {
  const map = {
    normal: { bg: C.mossSoft, fg: C.mossDeep },
    warning: { bg: C.goldSoft, fg: C.goldDeep },
    high: { bg: C.rustSoft, fg: C.rustDeep },
    critical: { bg: C.rustSoft, fg: C.rustDeep },
    none: { bg: C.surfaceSoft, fg: C.inkSoft },
  };
  return map[level] || map.none;
}

function fmtMonthShortUz(d) {
  return `${UZ_MONTHS_SHORT[d.getMonth()]} ${String(d.getFullYear()).slice(2)}`;
}

// Kelgusi `days` kun uchun kunlik Cash Forecast (bo'lim 9, 20):
// Closing Cash = Opening Cash + Planned Inflows - Planned Outflows.
function buildCashForecastDaily(occurrences, currentBalance, days) {
  const rows = [];
  let opening = currentBalance;
  const startD = new Date(todayStr());
  for (let i = 0; i < days; i++) {
    const d = new Date(startD.getFullYear(), startD.getMonth(), startD.getDate() + i);
    const ds = d.toISOString().slice(0, 10);
    const dayOcc = occurrences.filter((o) => o.date === ds);
    const inflow = dayOcc.filter((o) => o.type === "INCOME" && o.confidence !== "Possible").reduce((s, o) => s + o.amount, 0);
    const outflow = dayOcc.filter((o) => o.type === "EXPENSE").reduce((s, o) => s + o.amount, 0);
    const closing = opening + inflow - outflow;
    rows.push({ date: ds, opening, inflow, outflow, closing });
    opening = closing;
  }
  return rows;
}

// Rolling 12 oylik jadval (bo'lim 27, 31): har oy o'tganda keyingi oy avtomatik qo'shiladi,
// doim kelgusi 12 oy ko'rinadi.
function buildBudgetMonthlyTable(budgetItems, monthsCount) {
  const now = new Date();
  const monthsArr = [];
  for (let i = 0; i < monthsCount; i++) monthsArr.push(new Date(now.getFullYear(), now.getMonth() + i, 1));
  const rangeStart = monthsArr[0].toISOString().slice(0, 10);
  const lastMonthEnd = new Date(monthsArr[monthsCount - 1].getFullYear(), monthsArr[monthsCount - 1].getMonth() + 1, 0);
  const rangeEnd = lastMonthEnd.toISOString().slice(0, 10);
  const occ = buildBudgetOccurrences(budgetItems, rangeStart, rangeEnd).filter((o) => o.type === "EXPENSE");
  const rows = BUDGET_CATEGORIES.map((cat) => {
    const monthly = monthsArr.map((m) => {
      const ms = m.toISOString().slice(0, 7);
      return occ.filter((o) => o.category === cat && o.date.slice(0, 7) === ms).reduce((s, o) => s + o.amount, 0);
    });
    const total = monthly.reduce((s, v) => s + v, 0);
    return { category: cat, monthly, total };
  }).filter((r) => r.total > 0);
  const monthTotals = monthsArr.map((_, i) => rows.reduce((s, r) => s + r.monthly[i], 0));
  const grandTotal = monthTotals.reduce((s, v) => s + v, 0);
  return { monthLabels: monthsArr.map(fmtMonthShortUz), rows, monthTotals, grandTotal };
}

// Joriy oy uchun kategoriya bo'yicha Budget vs Actual (bo'lim 7, 23, 24).
function buildBudgetCategoryRows(budgetItems, expenses, monthDate) {
  const monthStart = new Date(monthDate.getFullYear(), monthDate.getMonth(), 1);
  const monthEnd = new Date(monthDate.getFullYear(), monthDate.getMonth() + 1, 0);
  const rs = monthStart.toISOString().slice(0, 10);
  const re = monthEnd.toISOString().slice(0, 10);
  const occ = buildBudgetOccurrences(budgetItems, rs, re).filter((o) => o.type === "EXPENSE");
  const rows = BUDGET_CATEGORIES.map((cat) => {
    const budget = occ.filter((o) => o.category === cat).reduce((s, o) => s + o.amount, 0);
    const actual = (expenses || [])
      .filter((e) => e.category === cat && inRange(e.date, startOfDay(monthStart), endOfDay(monthEnd)))
      .reduce((s, e) => s + (Number(e.amount) || 0), 0);
    const vs = varianceStatus(budget, actual);
    return { category: cat, budget, actual, ...vs };
  }).filter((r) => r.budget > 0 || r.actual > 0);
  return rows;
}

// Butun budget moduli uchun markazlashgan hisob-kitob (forecast, alertlar, KPIlar).
function computeBudgetData(budgetItems, cashStats, minCashReserve, expenses, animals, feedStats) {
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  const in7 = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 7);
  const in30 = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 30);

  const occCurrentMonth = buildBudgetOccurrences(
    budgetItems,
    monthStart.toISOString().slice(0, 10),
    monthEnd.toISOString().slice(0, 10)
  );
  const currentMonthBudget = occCurrentMonth.filter((o) => o.type === "EXPENSE").reduce((s, o) => s + o.amount, 0);
  const currentMonthActual = (expenses || [])
    .filter((e) => inRange(e.date, startOfDay(monthStart), endOfDay(monthEnd)))
    .reduce((s, e) => s + (Number(e.amount) || 0), 0);
  const remainingBudget = currentMonthBudget - currentMonthActual;
  const utilizationPct = currentMonthBudget > 0 ? (currentMonthActual / currentMonthBudget) * 100 : 0;

  const occ30 = buildBudgetOccurrences(budgetItems, todayStr(), in30.toISOString().slice(0, 10));
  const occ7 = occ30.filter((o) => o.date <= in7.toISOString().slice(0, 10));
  const upcoming7Total = occ7.filter((o) => o.type === "EXPENSE").reduce((s, o) => s + o.amount, 0);
  const upcoming30Total = occ30.filter((o) => o.type === "EXPENSE").reduce((s, o) => s + o.amount, 0);
  const expectedIncome30 = occ30.filter((o) => o.type === "INCOME").reduce((s, o) => s + o.amount, 0);

  const occ365 = buildBudgetOccurrences(budgetItems, todayStr(), addMonthsStr(todayStr(), 12).toISOString().slice(0, 10));
  const cashForecastDaily = buildCashForecastDaily(occ365, cashStats?.balance || 0, 60);
  const forecastClosingCash = cashForecastDaily.length ? cashForecastDaily[cashForecastDaily.length - 1].closing : cashStats?.balance || 0;
  const shortageRow = cashForecastDaily.find((r) => r.closing < 0);
  const lowReserveRow = !shortageRow ? cashForecastDaily.find((r) => r.closing >= 0 && r.closing < (Number(minCashReserve) || 0)) : null;

  const upcomingPayments = occ30
    .filter((o) => o.type === "EXPENSE")
    .map((o) => ({ ...o, status: occurrenceStatus(o.date), daysLeft: Math.round((new Date(o.date) - startOfDay(now)) / 86400000) }));

  const categoryRows = buildBudgetCategoryRows(budgetItems, expenses, now);
  const unplanned = categoryRows.filter((r) => r.status === "REJALASHTIRILMAGAN XARAJAT");
  const monthlyTable = buildBudgetMonthlyTable(budgetItems, 12);

  // AI tahlil (bo'lim 32) — real ma'lumotlar asosidagi oddiy og'zaki xulosalar.
  const aiInsights = [];
  const feedShare = upcoming30Total > 0
    ? (occ30.filter((o) => o.type === "EXPENSE" && o.category === "Ozuqa").reduce((s, o) => s + o.amount, 0) / upcoming30Total) * 100
    : 0;
  if (feedShare > 0) aiInsights.push(`Keyingi 30 kun xarajatlarining ${feedShare.toFixed(0)}% ozuqaga to'g'ri kelmoqda.`);
  if (shortageRow) aiInsights.push(`${fmtDateUz(shortageRow.date)} kuni kutilayotgan pul qoldig'i ${fmtSom(shortageRow.closing)} so'mga tushishi mumkin — CRITICAL CASH SHORTAGE.`);
  else if (lowReserveRow) aiInsights.push(`${fmtDateUz(lowReserveRow.date)} kuni cash reserve minimal darajadan pastga tushishi mumkin.`);
  const overBudgetCats = categoryRows.filter((r) => r.level === "high" || r.level === "critical");
  if (overBudgetCats.length) aiInsights.push(`Budgetdan oshgan kategoriyalar: ${overBudgetCats.map((r) => r.category).join(", ")}.`);
  if (unplanned.length) aiInsights.push(`Rejalashtirilmagan xarajatlar: ${unplanned.map((r) => r.category).join(", ")}.`);
  if ((animals || []).length && feedStats) {
    const perHead = animals.length > 0 ? (feedStats.monthChiqim || 0) / animals.length : 0;
    if (perHead > 0) aiInsights.push(`Har bir bosh chorvaga oylik ozuqa xarajati taxminan ${fmtShort(perHead)} ni tashkil etadi (${animals.length} bosh).`);
  }

  // Alert engine (bo'lim 22).
  const alerts = [];
  upcomingPayments
    .filter((o) => o.mandatory && (o.status === "DUE" || o.status === "OVERDUE" || o.daysLeft <= 3))
    .slice(0, 8)
    .forEach((o) => {
      alerts.push({
        type: o.status === "OVERDUE" ? "OVERDUE_PAYMENT" : o.status === "DUE" ? "PAYMENT_DUE" : "UPCOMING_PAYMENT",
        severity: o.status === "OVERDUE" ? "CRITICAL" : o.status === "DUE" ? "HIGH" : "MEDIUM",
        message: o.status === "OVERDUE"
          ? `To'lov muddati o'tgan: ${o.name} — ${fmtSom(o.amount)} so'm (${fmtDateUz(o.date)}).`
          : o.daysLeft === 0
          ? `To'lov muddati bugun: ${o.name} — ${fmtSom(o.amount)} so'm.`
          : `${o.daysLeft} kundan keyin ${fmtSom(o.amount)} so'm ${o.name} to'lovi mavjud.`,
      });
    });
  if (upcoming7Total > 0) {
    alerts.push({ type: "UPCOMING_PAYMENT", severity: "INFO", message: `Keyingi 7 kun ichida jami ${fmtSom(upcoming7Total)} so'mlik majburiy to'lov mavjud.` });
  }
  categoryRows.filter((r) => r.level === "critical" && r.status !== "REJALASHTIRILMAGAN XARAJAT").forEach((r) => {
    alerts.push({ type: "BUDGET_EXCEEDED", severity: "CRITICAL", message: `${r.category}: budget ${fmtSom(r.budget)}, actual ${fmtSom(r.actual)} — ${r.status} (${r.pct > 0 ? "+" : ""}${r.pct.toFixed(0)}%).` });
  });
  categoryRows.filter((r) => r.level === "warning" || r.level === "high").forEach((r) => {
    alerts.push({ type: "BUDGET_WARNING", severity: r.level === "high" ? "HIGH" : "MEDIUM", message: `${r.category}: variance ${r.pct > 0 ? "+" : ""}${r.pct.toFixed(0)}% (${r.status}).` });
  });
  unplanned.forEach((r) => {
    alerts.push({ type: "UNPLANNED_EXPENSE", severity: "HIGH", message: `${r.category} bo'yicha reja yo'q edi, lekin ${fmtSom(r.actual)} so'm xarajat qilindi.` });
  });
  if (shortageRow) alerts.push({ type: "CASH_SHORTAGE", severity: "CRITICAL", message: `${fmtDateUz(shortageRow.date)} — CRITICAL CASH SHORTAGE: forecast ${fmtSom(shortageRow.closing)} so'm.` });
  else if (lowReserveRow) alerts.push({ type: "LOW_CASH_RESERVE", severity: "MEDIUM", message: `${fmtDateUz(lowReserveRow.date)} — kutilayotgan pul qoldig'i minimal rezervdan ${fmtSom((Number(minCashReserve) || 0) - lowReserveRow.closing)} so'm past.` });

  return {
    currentMonthBudget, currentMonthActual, remainingBudget, utilizationPct,
    upcoming7Total, upcoming30Total, expectedIncome30,
    forecastClosingCash, shortageRow, lowReserveRow, cashForecastDaily,
    upcomingPayments, categoryRows, unplanned, monthlyTable, aiInsights, alerts,
  };
}

// Sidebar va asosiy kontent bir xil qiymatga tayanishi uchun yagona manba.
// Shu tufayli margin-left sidebar width'idan hech qachon 1px ham farq qilmaydi.
const SIDEBAR_WIDTH = 240;

// =====================================================================
// SOZLAMALAR / XODIMLAR / RBAC / AUTENTIFIKATSIYA
// =====================================================================
//
// MUHIM (shaffoflik uchun): bu ERP hozircha Claude Artifact muhitida
// window.storage orqali ishlaydi — bu haqiqiy backend server EMAS.
// Shu sabab:
//  - Parollar oddiy matnda emas, balki SHA-256 + tuz (salt) bilan xeshlanib
//    saqlanadi (quyida hashPassword/verifyPassword). Bu "parol ochiq matnda
//    saqlanmasin" talabini bajaradi, lekin production darajadagi tizimda
//    server tomonida bcrypt/Argon2 + haqiqiy JWT/serverga asoslangan RBAC
//    ishlatish tavsiya etiladi — buni frontend-only muhitda to'liq
//    takrorlab bo'lmaydi.
//  - "Session" shu brauzerda window.storage(personal) orqali saqlanadi.
//  - Xodimlar ro'yxati va audit-jurnal "shared" xotirada saqlanadi — shu
//    havolani ochgan barcha odamlar bitta xodimlar bazasini ko'radi
//    (kompaniya darajasidagi ro'yxat sifatida). Boshqa modullar (chorva,
//    kassa, ombor va h.k.) hozircha shaxsiy (shared:false) rejimda qolmoqda
//    — ular bu vazifa doirasida o'zgartirilmadi.
//  - RBAC sidebar va asosiy kontent darajasida markazlashtirilgan tarzda
//    (bitta joyda) tekshiriladi, shunda "view" holati qanday o'zgarmasin
//    (hatto dasturiy xato bo'lsa ham) ruxsatsiz bo'lim ko'rsatilmaydi.

const MODULES = [
  { key: "dashboard", label: "Dashboard" },
  { key: "registry", label: "Chorva reyestri" },
  { key: "insemination", label: "Sigirlarni urug'lantirish" },
  { key: "feed", label: "Ombor / Ozuqa" },
  { key: "meds", label: "Dori / Veterinariya" },
  { key: "expenses", label: "Xarajatlar" },
  { key: "cash", label: "Kassa / Pul oqimi" },
  { key: "finance", label: "Moliya / P&L" },
  { key: "budget", label: "BUDJET" },
  { key: "balance", label: "Balans" },
  { key: "arReceivables", label: "Debitorlar" },
  { key: "arPayables", label: "Kreditorlar" },
  { key: "arCounterparties", label: "Kontragentlar" },
  { key: "arPayments", label: "To'lovlar" },
  { key: "arAging", label: "Qarzdorlik hisoboti" },
  { key: "settingsEmployees", label: "Sozlamalar — Xodimlar" },
];
const MODULE_KEYS = MODULES.map((m) => m.key);

const ROLES = [
  { key: "administrator", label: "Administrator" },
  { key: "director", label: "Direktor" },
  { key: "accountant", label: "Buxgalter" },
  { key: "vet", label: "Veterinar" },
  { key: "warehouse", label: "Omborchi" },
  { key: "staff", label: "Oddiy xodim" },
];
const roleLabel = (key) => ROLES.find((r) => r.key === key)?.label || key;

// Har bir rol uchun standart modul ro'yxati (xodim qo'shilganda shu asosda
// boshlang'ich ruxsatlar hosil qilinadi; administrator keyin har bir xodim
// uchun buni alohida moslashtira oladi — bo'lim 4).
const ROLE_FULL_MODULES = {
  administrator: MODULE_KEYS,
  director: ["dashboard", "registry", "insemination", "feed", "finance", "budget", "balance", "arAging"],
  accountant: ["expenses", "cash", "finance", "arAging"],
  vet: ["registry", "insemination", "meds"],
  warehouse: ["feed"],
  staff: [],
};
// Direktor "Xodimlar"ni faqat ko'ra oladi (talab: "xodimlarni ko'rish").
const ROLE_VIEW_ONLY_MODULES = {
  director: ["settingsEmployees"],
};

function emptyPermissions() {
  const perms = {};
  MODULE_KEYS.forEach((k) => {
    perms[k] = { view: false, add: false, edit: false, delete: false };
  });
  return perms;
}

function buildDefaultPermissions(role) {
  const perms = emptyPermissions();
  (ROLE_FULL_MODULES[role] || []).forEach((k) => {
    perms[k] = { view: true, add: true, edit: true, delete: true };
  });
  (ROLE_VIEW_ONLY_MODULES[role] || []).forEach((k) => {
    perms[k] = { view: true, add: false, edit: false, delete: false };
  });
  if (role === "administrator") {
    MODULE_KEYS.forEach((k) => {
      perms[k] = { view: true, add: true, edit: true, delete: true };
    });
  }
  return perms;
}

function hasPermission(user, moduleKey, action = "view") {
  if (!user) return false;
  if (user.role === "administrator") return true;
  const perm = user.permissions && user.permissions[moduleKey];
  return !!(perm && perm[action]);
}

function firstAllowedModule(user) {
  const m = MODULES.find((m) => hasPermission(user, m.key, "view"));
  return m ? m.key : "dashboard";
}

// ---- Parol xeshlash (Web Crypto: SHA-256 + tasodifiy tuz) ----
function randomHex(byteLen) {
  const arr = new Uint8Array(byteLen);
  (window.crypto || window.msCrypto).getRandomValues(arr);
  return Array.from(arr).map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function sha256Hex(text) {
  const enc = new TextEncoder();
  const buf = await window.crypto.subtle.digest("SHA-256", enc.encode(text));
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function hashPassword(plainPassword) {
  const salt = randomHex(16);
  const hash = await sha256Hex(`${salt}:${plainPassword}`);
  return { salt, hash };
}

async function verifyPassword(plainPassword, salt, hash) {
  const check = await sha256Hex(`${salt}:${plainPassword}`);
  return check === hash;
}

function genTempPassword() {
  // O'qish oson, lekin yetarlicha tasodifiy vaqtinchalik parol.
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let out = "";
  for (let i = 0; i < 8; i++) out += chars[Math.floor(Math.random() * chars.length)];
  return out;
}

