// ---------- Header'dagi foydalanuvchi chip'i va chiqish tugmasi ----------
function UserMenu({ currentUser, onLogout }) {
  const C = useContext(ThemeContext);
  const [open, setOpen] = useState(false);
  const wrapRef = useRef(null);

  useEffect(() => {
    function onOutside(e) {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", onOutside);
    return () => document.removeEventListener("mousedown", onOutside);
  }, []);

  if (!currentUser) return null;

  return (
    <div className="relative shrink-0" ref={wrapRef}>
      <button
        onClick={() => setOpen((o) => !o)}
        className="flex items-center gap-2 pl-2.5 pr-3 py-2 rounded-xl text-sm"
        style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: C.shadow, color: C.ink }}
      >
        <div
          className="w-7 h-7 rounded-full flex items-center justify-center text-xs font-semibold text-white shrink-0"
          style={{ background: GRAD.moss }}
        >
          {(currentUser.fullName || currentUser.login || "?").trim().charAt(0).toUpperCase()}
        </div>
        <span className="hidden sm:flex flex-col items-start leading-tight">
          <span className="text-xs font-medium">{currentUser.fullName || currentUser.login}</span>
          <span className="text-[10px]" style={{ color: C.inkSoft }}>{roleLabel(currentUser.role)}</span>
        </span>
        <ChevronDown size={14} style={{ color: C.inkSoft }} />
      </button>
      {open && (
        <div
          className="absolute right-0 mt-2 z-20 rounded-xl overflow-hidden min-w-[180px]"
          style={{ background: C.surface, border: `1px solid ${C.line}`, boxShadow: C.shadow }}
        >
          <div className="px-3.5 py-3" style={{ borderBottom: `1px solid ${C.line}` }}>
            <div className="text-sm font-medium" style={{ color: C.ink }}>{currentUser.fullName}</div>
            <div className="text-xs" style={{ color: C.inkSoft }}>{currentUser.login} · {roleLabel(currentUser.role)}</div>
          </div>
          <button
            onClick={() => {
              setOpen(false);
              onLogout();
            }}
            className="w-full flex items-center gap-2 px-3.5 py-2.5 text-sm hover:opacity-80"
            style={{ color: "#9C3F28" }}
          >
            <LogOut size={15} /> Chiqish
          </button>
        </div>
      )}
    </div>
  );
}

